        self.components = n
    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x
    def union(self, a: int, b: int) -> bool:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        dsu = DSU(n)
        # Indices with value <= threshold
        indices = [i for i, v in enumerate(nums) if v <= threshold]
        if not indices:
            return n
        # Build divisor lists
        divs = [[] for _ in range(threshold + 1)]
        for idx in indices:
            val = nums[idx]
            for m in range(val, threshold + 1, val):
                divs[m].append(idx)
        # Union nodes sharing a common multiple
        for lst in divs[1:]:
            if len(lst) > 1:
                first = lst[0]
                for other in lst[1:]:
                    dsu.union(first, other)
        return dsu.components

