def f_of_seq(a):
    n=len(a)
    g=[set() for _ in range(n)]
    for i in range(n):
        for j in range(i+1,n):
            if a[i]<=a[j]:
                g[i].add(j)
                g[j].add(i)
    visited=[False]*n
    comp=0
    def dfs(u):
        stack=[u]
        visited[u]=True
        while stack:
            v=stack.pop()
            for w in g[v]:
                if not visited[w]:
                    visited[w]=True
                    stack.append(w)
    for i in range(n):
        if not visited[i]:
            comp+=1
            dfs(i)
    return comp

