"""
Solution for: smallest-substring-with-identical-characters-i
Problem ID: lcb_3690

Implement the function below.
"""

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        def can(L: int) -> bool:
            INF = 10 ** 9
            dp_prev = [[INF] * (L + 1) for _ in range(2)]
            for c in (0, 1):
                dp_prev[c][1] = 0 if s[0] == str(c) else 1
            for i in range(1, n):
                dp_cur = [[INF] * (L + 1) for _ in range(2)]
                for prev_c in (0, 1):
                    for l in range(1, L + 1):
                        flips_prev = dp_prev[prev_c][l]
                        if flips_prev == INF:
                            continue
                        for new_c in (0, 1):
                            if new_c == prev_c:
                                new_l = l + 1
                                if new_l > L:
                                    continue
                            else:
                                new_l = 1
                            flip_cost = 0 if s[i] == str(new_c) else 1
                            flips = flips_prev + flip_cost
                            if flips < dp_cur[new_c][new_l]:
                                dp_cur[new_c][new_l] = flips
                dp_prev = dp_cur
            for c in (0, 1):
                if min(dp_prev[c]) <= numOps:
                    return True
            return False
        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            if can(mid):
                high = mid
            else:
                low = mid + 1
        return low

if __name__ == "__main__":
    sol = Solution()
    print(sol.minLength("000001", 1))
    print(sol.minLength("0000", 2))
    print(sol.minLength("0101", 0))

