        elif a > 0 and b > 0 and c == 0:
            for pre_start in occ_pre:
                pre_end = pre_start + a - 1
                target_mid = pre_end + 1
                mid_start = ge(occ_mid, target_mid)
                if mid_start is None:
                    continue
                length = mid_start + b - pre_start
                if length < best:
