import sys


def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it)); Q = int(next(it))
    H = [0]*(N+1)
    for i in range(1, N+1):
        H[i] = int(next(it))
    # compute prev taller index
    prev = [0]*(N+1)
    st = []  # stack of indices with decreasing heights
    for k in range(1, N+1):
        while st and H[st[-1]] < H[k]:
            st.pop()
        prev[k] = st[-1] if st else 0
        st.append(k)
    queries_by_r = [[] for _ in range(N+1)]
    res = [0]*Q
    for idx in range(Q):
        l = int(next(it)); r = int(next(it))
        queries_by_r[r].append((l, idx))
    size = N+2
    bit = [0]*(size)
    def bit_add(i, delta):
        while i < size:
            bit[i] += delta
            i += i & -i
    def bit_sum(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s
    # process from right to left
    for k in range(N, 0, -1):
        bit_add(prev[k]+1, 1)
        r = k-1
        if r >= 0:
            for l, idx in queries_by_r[r]:
                # need buildings with prev <= l
                # their index in BIT is prev+1, so count those with prev+1 <= l+1
                res[idx] = bit_sum(l+1)
    sys.stdout.write("\n".join(map(str, res)))

if __name__ == "__main__":
    solve()

